    float ssh92_shadow = 1.0;
    float2 ssh92_uvStep = ssh92_Lt.xy * (node95_out) * 0.01;
    [unroll] for (int ssh92_i = 1; ssh92_i <= 8; ++ssh92_i)
    {
        float2 ssh92_suv = In.uv + ssh92_uvStep * ssh92_i;
        float ssh92_hs = dot(g_modelBaseColor.Sample(g_sampler, ssh92_suv).rgb, float3(0.299,0.587,0.114));
        float ssh92_expected = ssh92_h0 + ssh92_Lt.z * ssh92_i * 0.05;
        if (ssh92_hs > ssh92_expected)
            ssh92_shadow = min(ssh92_shadow, 1.0 - (ssh92_hs - ssh92_expected) * 5.0);
    }
    ssh92_shadow = saturate(lerp(1.0, ssh92_shadow, (node94_out)));
    float3 ssh92_result = (node90_out).rgb * ssh92_shadow;
    float4 node92_out = float4(ssh92_result, (node90_out).a);
    float nfh85_str = 0.0299999993f;
    float3 nfh85_rawN = In.worldNormal;
    float  nfh85_lenN = length(nfh85_rawN);
    float3 nfh85_N = (nfh85_lenN > 1e-5) ? (nfh85_rawN / nfh85_lenN) : float3(0.0, 1.0, 0.0);
    float3 nfh85_rawT = In.worldTangent - dot(In.worldTangent, nfh85_N) * nfh85_N;
    float  nfh85_lenT = length(nfh85_rawT);
    float3 nfh85_fb = (abs(nfh85_N.y) < 0.99) ? float3(0.0, 1.0, 0.0) : float3(1.0, 0.0, 0.0);
    float3 nfh85_T = (nfh85_lenT > 1e-5) ? (nfh85_rawT / nfh85_lenT) : normalize(cross(nfh85_fb, nfh85_N));
    float3 nfh85_B = cross(nfh85_N, nfh85_T);
    float4 nfh85_col = node92_out;
    float nfh85_h = dot(nfh85_col.rgb, float3(0.2126, 0.7152, 0.0722)) * nfh85_str;
    float3 nfh85_dpdx = ddx(In.worldPos);
    float3 nfh85_dpdy = ddy(In.worldPos);
    float3 nfh85_R1 = cross(nfh85_dpdy, nfh85_N);
    float3 nfh85_R2 = cross(nfh85_N, nfh85_dpdx);
    float  nfh85_det = dot(nfh85_dpdx, nfh85_R1);
    float3 nfh85_grad = sign(nfh85_det) * (ddx(nfh85_h) * nfh85_R1 + ddy(nfh85_h) * nfh85_R2);
    float3 nfh85_result = normalize(abs(nfh85_det) * nfh85_N - nfh85_grad);
    float3 nfh85_texN = float3(dot(nfh85_result, nfh85_T), dot(nfh85_result, nfh85_B), dot(nfh85_result, nfh85_N));
    float3 node85_out = nfh85_result;
    float4 node89_out = float4(0.107142866f, 0.0747847557f, 0.0440051034f, 1.0f);
    float node99_out = 1.0f;
    PS_OUT o;
    o.target0 = float4((node92_out).xyz, (g_modelMetalRough.Sample(g_sampler, In.uv).b * g_metallicRate));
    o.target1 = float4((nfh85_result) * 0.5 + 0.5, (g_modelMetalRough.Sample(g_sampler, In.uv).g * g_roughnessRate));
    o.target2 = float4(In.worldPos, 1.0);
    o.target3 = float4((node89_out).xyz, node99_out);
    o.target4 = float4(0,0,0,0);
    return o;
}

